  1→import { Hono } from "hono";
  2→import type { Env, SyncResult } from "../types";
  3→
  4→const app = new Hono<{ Bindings: Env }>();
  5→
  6→// --- Types ---
  7→
  8→interface PageInfo {
  9→  hasNextPage: boolean;
 10→  endCursor: string | null;
 11→}
 12→
 13→interface LinearIssue {
 14→  id: string;
 15→  identifier: string;
 16→  title: string;
 17→  description: string | null;
 18→  priority: number;
 19→  estimate: number | null;
 20→  state: { name: string; type: string } | null;
 21→  labels: { nodes: { name: string }[] };
 22→  project: { name: string } | null;
 23→  cycle: { number: number } | null;
 24→  assignee: { name: string } | null;
 25→  createdAt: string;
 26→  updatedAt: string;
 27→  startedAt: string | null;
 28→  completedAt: string | null;
 29→  canceledAt: string | null;
 30→  dueDate: string | null;
 31→}
