202→async function syncProjects(db: D1Database, apiKey: string): Promise<number> {
203→  const projects = await fetchAllPages<LinearProject>(apiKey, PROJECTS_QUERY, "projects");
204→
205→  const statements = projects.map((project) => {
206→    return db
207→      .prepare(
208→        `INSERT INTO linear_projects (id, name, state, progress, start_date, target_date,
209→           created_at, updated_at, completed_at, synced_at)
210→         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
211→         ON CONFLICT(id) DO UPDATE SET
212→           name = excluded.name,
213→           state = excluded.state,
214→           progress = excluded.progress,
215→           start_date = excluded.start_date,
216→           target_date = excluded.target_date,
217→           updated_at = excluded.updated_at,
218→           completed_at = excluded.completed_at,
219→           synced_at = excluded.synced_at`
220→      )
