241→async function syncLabels(db: D1Database, apiKey: string): Promise<number> {
242→  const data = await fetchLinearGraphQL<{ issueLabels: { nodes: LinearLabel[] } }>(
243→    LABELS_QUERY,
244→    {},
245→    apiKey
246→  );
247→  const labels = data.issueLabels.nodes;
248→
249→  const statements = labels.map((label) => {
250→    return db
251→      .prepare(
252→        `INSERT INTO linear_labels (id, name, color, synced_at)
253→         VALUES (?, ?, ?, datetime('now'))
254→         ON CONFLICT(id) DO UPDATE SET
255→           name = excluded.name,
256→           color = excluded.color,
257→           synced_at = excluded.synced_at`
258→      )
259→      .bind(label.id, label.name, label.color);
