 80→// Measure type codes
 81→const MEASURE_TYPES: Record<number, string> = {
 82→  1: "weight",
 83→  5: "fat_free_mass",
 84→  6: "fat_ratio",
 85→  8: "fat_mass",
 86→  11: "heart_pulse",
