import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { beforeAll, describe, expect, it } from "vitest";
import {
  encodeDailyActivity,
  encodeDailyReadiness,
  encodeDailySleep,
  encodeHeartRate,
  initParquetWasm,
} from "../services/parquet";

beforeAll(() => {
  const wasmPath = resolve(__dirname, "../../node_modules/parquet-wasm/esm/parquet_wasm_bg.wasm");
  const wasmBytes = readFileSync(wasmPath);
  initParquetWasm(wasmBytes);
});

function expectParquetMagic(buffer: Uint8Array) {
  expect(buffer).toBeInstanceOf(Uint8Array);
  expect(buffer.length).toBeGreaterThan(0);
  // Parquet magic bytes: PAR1
  expect(buffer[0]).toBe(0x50); // P
  expect(buffer[1]).toBe(0x41); // A
  expect(buffer[2]).toBe(0x52); // R
  expect(buffer[3]).toBe(0x31); // 1
}

describe("encodeDailySleep", () => {
  it("should encode sleep data to valid Parquet", async () => {
    const data = [
      {
        day: "2026-03-12",
        score: 85,
        deep_sleep: 70,
        efficiency: 90,
        latency: 80,
        rem_sleep: 75,
        restfulness: 88,
        timing: 92,
        total_sleep: 82,
        timestamp: "2026-03-12T07:00:00+00:00",
        synced_at: "2026-03-12T09:00:00Z",
      },
    ];
    const buffer = await encodeDailySleep(data);
    expectParquetMagic(buffer);
  });

  it("should handle nullable fields", async () => {
    const data = [
      {
        day: "2026-03-12",
        score: null,
        deep_sleep: null,
        efficiency: null,
        latency: null,
        rem_sleep: null,
        restfulness: null,
        timing: null,
        total_sleep: null,
        timestamp: "2026-03-12T07:00:00+00:00",
        synced_at: "2026-03-12T09:00:00Z",
      },
    ];
    const buffer = await encodeDailySleep(data);
    expectParquetMagic(buffer);
  });
});

describe("encodeDailyActivity", () => {
  it("should encode activity data to valid Parquet", async () => {
    const data = [
      {
        day: "2026-03-12",
        score: 90,
        active_calories: 450,
        total_calories: 2200,
        steps: 8500,
        equivalent_walking_distance: 6500.5,
        high_activity_time: 1800,
        medium_activity_time: 3600,
        low_activity_time: 7200,
        sedentary_time: 28800,
        resting_time: 32400,
        met_average: 1.8,
        meet_daily_targets: 80,
        move_every_hour: 75,
        recovery_time: 85,
        stay_active: 70,
        training_frequency: 60,
        training_volume: 65,
        timestamp: "2026-03-12T23:59:59+00:00",
        synced_at: "2026-03-13T00:05:00Z",
      },
    ];
    const buffer = await encodeDailyActivity(data);
    expectParquetMagic(buffer);
  });
});

describe("encodeDailyReadiness", () => {
  it("should encode readiness data to valid Parquet", async () => {
    const data = [
      {
        day: "2026-03-12",
        score: 88,
        temperature_deviation: 0.15,
        temperature_trend_deviation: -0.05,
        activity_balance: 80,
        body_temperature: 85,
        hrv_balance: 78,
        previous_day_activity: 90,
        previous_night: 88,
        recovery_index: 82,
        resting_heart_rate: 75,
        sleep_balance: 86,
        timestamp: "2026-03-12T07:00:00+00:00",
        synced_at: "2026-03-12T09:00:00Z",
      },
    ];
    const buffer = await encodeDailyReadiness(data);
    expectParquetMagic(buffer);
  });
});

describe("encodeHeartRate", () => {
  it("should encode heart rate data to valid Parquet", async () => {
    const data = [
      {
        bpm: 72,
        source: "awake",
        timestamp: "2026-03-12T10:00:00+00:00",
        day: "2026-03-12",
        synced_at: "2026-03-12T12:00:00Z",
      },
      {
        bpm: 65,
        source: "rest",
        timestamp: "2026-03-12T10:05:00+00:00",
        day: "2026-03-12",
        synced_at: "2026-03-12T12:00:00Z",
      },
    ];
    const buffer = await encodeHeartRate(data);
    expectParquetMagic(buffer);
  });
});

import { env, fetchMock, SELF } from "cloudflare:test";
import { afterEach, beforeAll, describe, expect, it } from "vitest";

const OURA_MIGRATION_SQL = `
CREATE TABLE IF NOT EXISTS oauth_tokens (
    id TEXT PRIMARY KEY,
    access_token TEXT NOT NULL,
    refresh_token TEXT NOT NULL,
    token_type TEXT DEFAULT 'Bearer',
    expires_at TEXT NOT NULL,
    scope TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS oura_daily_sleep (
    id TEXT PRIMARY KEY,
    day TEXT NOT NULL UNIQUE,
    score INTEGER,
    timestamp TEXT,
    deep_sleep INTEGER,
    efficiency INTEGER,
    latency INTEGER,
    rem_sleep INTEGER,
    restfulness INTEGER,
    timing INTEGER,
    total_sleep INTEGER,
    synced_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS oura_daily_activity (
    id TEXT PRIMARY KEY,
    day TEXT NOT NULL UNIQUE,
    score INTEGER,
    active_calories INTEGER,
    total_calories INTEGER,
    steps INTEGER,
    equivalent_walking_distance REAL,
    high_activity_time INTEGER,
    medium_activity_time INTEGER,
    low_activity_time INTEGER,
    sedentary_time INTEGER,
    resting_time INTEGER,
    met_average REAL,
    meet_daily_targets INTEGER,
    move_every_hour INTEGER,
    recovery_time INTEGER,
    stay_active INTEGER,
    training_frequency INTEGER,
    training_volume INTEGER,
    timestamp TEXT,
    synced_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS oura_daily_readiness (
    id TEXT PRIMARY KEY,
    day TEXT NOT NULL UNIQUE,
    score INTEGER,
    temperature_deviation REAL,
    temperature_trend_deviation REAL,
    timestamp TEXT,
    activity_balance INTEGER,
    body_temperature INTEGER,
    hrv_balance INTEGER,
    previous_day_activity INTEGER,
    previous_night INTEGER,
    recovery_index INTEGER,
    resting_heart_rate INTEGER,
    sleep_balance INTEGER,
    synced_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS oura_heart_rate (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bpm INTEGER NOT NULL,
    source TEXT,
    timestamp TEXT NOT NULL,
    day TEXT NOT NULL,
    synced_at TEXT DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_oura_daily_sleep_day ON oura_daily_sleep(day DESC);
CREATE INDEX IF NOT EXISTS idx_oura_daily_activity_day ON oura_daily_activity(day DESC);
CREATE INDEX IF NOT EXISTS idx_oura_daily_readiness_day ON oura_daily_readiness(day DESC);
CREATE INDEX IF NOT EXISTS idx_oura_heart_rate_day ON oura_heart_rate(day DESC);
CREATE INDEX IF NOT EXISTS idx_oura_heart_rate_timestamp ON oura_heart_rate(timestamp DESC);

CREATE VIEW IF NOT EXISTS v_oura_daily_summary AS
SELECT
    s.day,
    s.score AS sleep_score,
    a.score AS activity_score,
    r.score AS readiness_score,
    a.steps,
    a.total_calories,
    a.active_calories,
    r.temperature_deviation,
    s.deep_sleep AS sleep_deep_sleep,
    s.efficiency AS sleep_efficiency,
    s.total_sleep AS sleep_total_sleep
FROM oura_daily_sleep s
LEFT JOIN oura_daily_activity a ON s.day = a.day
LEFT JOIN oura_daily_readiness r ON s.day = r.day
ORDER BY s.day DESC;

CREATE TABLE IF NOT EXISTS data_sources (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    source_type TEXT NOT NULL,
    api_endpoint TEXT,
    schedule_cron TEXT,
    is_active INTEGER DEFAULT 1,
    config_json TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS sync_state (
    id TEXT PRIMARY KEY,
    data_source_id TEXT NOT NULL,
    last_sync_at TEXT,
    last_cursor TEXT,
    metadata_json TEXT,
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (data_source_id) REFERENCES data_sources(id)
);

INSERT OR IGNORE INTO data_sources (id, name, source_type, api_endpoint, schedule_cron)
VALUES ('oura', 'Oura Ring', 'api', 'https://api.ouraring.com', '0 0 * * *');

INSERT OR IGNORE INTO sync_state (id, data_source_id, last_sync_at)
VALUES ('oura', 'oura', NULL);
`;

async function insertTestToken(expiresAt?: string) {
  const expires = expiresAt ?? new Date(Date.now() + 3600 * 1000).toISOString();
  await env.DB.prepare(
    `INSERT OR REPLACE INTO oauth_tokens (id, access_token, refresh_token, expires_at)
     VALUES ('oura', 'test-access-token', 'test-refresh-token', ?)`
  )
    .bind(expires)
    .run();
}

beforeAll(async () => {
  const statements = OURA_MIGRATION_SQL.split(";")
    .map((s) => s.trim())
    .filter((s) => s.length > 0);

  for (const sql of statements) {
    await env.DB.prepare(sql).run();
  }

  fetchMock.activate();
  fetchMock.disableNetConnect();
});

afterEach(() => {
  fetchMock.assertNoPendingInterceptors();
});

describe("oura oauth2", () => {
  it("redirects to Oura auth page on GET /oura/auth", async () => {
    const res = await SELF.fetch("https://example.com/oura/auth", { redirect: "manual" });
    expect(res.status).toBe(302);

    const location = res.headers.get("Location") ?? "";
