// ============================================
// GitHub Row types
// ============================================

export interface GitHubUserRow {
  id: number;
  login: string;
  name: string | null;
  avatar_url: string;
  synced_at: string;
}

export interface GitHubRepoRow {
  id: number;
  owner_id: number;
  name: string;
  full_name: string;
  description: string | null;
  language: string | null;
  stars: number;
  forks: number;
