      query,
      { first: 50, after },
      apiKey
    );
    const connection = data[rootField];
    results.push(...connection.nodes);
    after = connection.pageInfo.hasNextPage ? connection.pageInfo.endCursor : null;
  } while (after);

  return results;
}

