    issues(first: $first, after: $after, orderBy: updatedAt) {
      nodes {
        id identifier title description
        priority estimate
        state { name type }
        labels { nodes { name } }
        project { name }
        cycle { number }
        assignee { name }
        createdAt updatedAt startedAt completedAt canceledAt
