import { tableFromArrays, tableToIPC } from "apache-arrow";
// Patch apache-arrow to avoid `new Function()` which is forbidden in Workers.
// `createIsValidFunction` normally uses `new Function()` for a 25% perf gain,
// but Workers disallow dynamic code generation. This safe replacement uses a
// Set-based lookup instead, which is functionally identical.
import * as arrowValid from "apache-arrow/builder/valid";
(arrowValid as { createIsValidFunction: unknown }).createIsValidFunction = (
  nullValues?: readonly unknown[]
) => {
  if (!nullValues || nullValues.length <= 0) {
    return () => true;
  }
  const hasNaN = nullValues.some((x) => x !== x);
  const nullSet = new Set(nullValues.filter((x) => x === x));
  return (value: unknown) => {
    if (hasNaN && typeof value === "number" && value !== value) return false;
    return !nullSet.has(value);
  };
};

