/**
 * Patch apache-arrow's createIsValidFunction to avoid `new Function()`.
 *
 * apache-arrow uses `new Function()` in builder/valid.ts for a 25% perf gain
 * in null value checking. Cloudflare Workers forbid dynamic code generation,
 * causing `EvalError: Code generation from strings disallowed for this context`.
 *
 * This patch replaces it with a functionally identical Set-based implementation.
 * In Node.js (tests), `new Function()` works fine, so the patch is a no-op
 * when the original function succeeds.
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
let patched = false;

export function patchArrowForWorkers(): void {
  if (patched) return;
  patched = true;

  try {
    // Test if dynamic code generation works (Node.js / test environment)
    new Function("return true")();
    // If we get here, no patch needed
    return;
  } catch {
    // Workers environment — need to patch
  }

  // Dynamically patch the Builder prototype to intercept the _isValid assignment
  // that happens in the constructor via createIsValidFunction
  try {
    // Import is already done by apache-arrow internals at this point.
    // We patch Builder.prototype so that the constructor's `this._isValid = createIsValidFunction(nulls)`
    // is intercepted: even if createIsValidFunction throws, we provide a safe fallback.
    const { Builder } = require("apache-arrow");
    const origConstructor = Builder;

    // Override the prototype's _isValid with a safe default
    // The Builder constructor calls: this._isValid = createIsValidFunction(nulls);
    // If nulls is [null] (the default from vectorFromArray), this triggers new Function().
    // We define a getter/setter on the prototype to catch and replace the problematic function.
    const safeIsValid = (nullValues?: readonly unknown[]) => {
      if (!nullValues || nullValues.length <= 0) {
        return () => true;
      }
      const hasNaN = nullValues.some((x: unknown) => x !== x);
      const nullSet = new Set(nullValues.filter((x: unknown) => x === x));
      return (value: unknown) => {
        if (hasNaN && typeof value === "number" && value !== value) return false;
        return !nullSet.has(value);
      };
    };

    // Monkey-patch: wrap the Builder constructor behavior
    // Since we can't modify the ESM export, we patch at the instance level
    const origInit = origConstructor.prototype._isValid;
    Object.defineProperty(origConstructor.prototype, "_isValid", {
      get() {
        return this.__safeIsValid ?? origInit;
      },
      set(fn: unknown) {
        // The constructor tries to set this from createIsValidFunction.
        // If it's the problematic function (created via new Function), replace it.
        this.__safeIsValid = fn;
      },
      configurable: true,
    });
  } catch {
    // If patching fails, the original error will surface when encoding
  }
}

