      const nulls = options?.nullValues;
      origCtor.call(this, { ...options, nullValues: undefined });
      this._isValid = safeIsValid(nulls);
    };
    // This approach won't work because the class constructor can't be replaced.
    // Instead, we rely on the getter/setter above to catch the assignment.
  } catch {
    // If patching fails, the original error will surface when encoding
  }
}

