  }

  const syncState = await c.env.DB.prepare(
    "SELECT last_sync_at FROM sync_state WHERE id = 'withings'"
  ).first<{ last_sync_at: string | null }>();

  return c.json({ ...stats, last_sync: syncState?.last_sync_at ?? null });
});

