async function syncActivity(
  r2: R2Bucket,
  encoder: Fetcher,
  token: string,
  startDate: string,
  endDate: string,
  synced_at: string
): Promise<number> {
  let offset = 0;
  const allRows: WithingsActivityRow[] = [];

  while (true) {
    const body = await postWithings<ActivityBody>(WITHINGS_ACTIVITY_URL, token, {
      action: "getactivity",
