import {
  encodeDailyActivity,
  encodeDailyReadiness,
  encodeDailySleep,
  encodeHeartRate,
  encodeGitHubUser,
  encodeGitHubRepo,
  encodeGitHubCommit,
  encodeLinearIssue,
  encodeLinearProject,
  encodeLinearLabel,
  encodeWithingsMeasure,
  encodeWithingsSleep,
  encodeWithingsActivity,
  initParquetWasm,
} from "../services/parquet";

beforeAll(() => {
