        synced_at: "2026-03-12T09:00:00Z",
      },
    ];
    const buffer = await encodeDailySleep(encoder, data);
    expect(buffer).toBeInstanceOf(Uint8Array);
    expect(buffer.length).toBeGreaterThan(0);
