  );

  if (data.length === 0) return 0;

  const synced_at = new Date().toISOString();
  const grouped = groupByDay(data, (item) => item.day);

  for (const [day, items] of grouped) {
    const rows: DailyReadinessRow[] = items.map((item) => ({
      day: item.day,
